package dev.alien.client.smoke;
import dev.alien.client.AlienClient;import dev.alien.client.scene.*;import dev.alien.client.config.*;import dev.alien.client.cosmetic.*;
import java.io.*;import java.nio.file.Files;import java.util.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.entity.item.EntityItem;import net.minecraft.init.*;import net.minecraft.item.ItemStack;import net.minecraft.util.*;import net.minecraft.world.*;
import net.minecraftforge.fml.common.*;import net.minecraftforge.fml.common.event.*;import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;import net.minecraftforge.fml.common.gameevent.TickEvent;import org.lwjgl.opengl.*;
@Mod(modid="alien_scene_smoke",name="Alien visual scenes validation",version="1",clientSideOnly=true,dependencies="required-after:alienclient")
public final class AlienSceneSmoke {
 private Minecraft m;private File out;private int stage;private long since,start,frames,bones,cute,glass,landings,bodyGlass,heldGlass,dropGlass;private boolean done,animationCaptured;private java.awt.Robot robot;private final Set<List<Integer>> skyFrames=new HashSet<List<Integer>>();private BufferedImage cosmic;private final List<String> checks=new ArrayList<String>();
 private ClientConfig c(){return AlienClient.get().config();}
 @Mod.EventHandler public void init(FMLInitializationEvent e)throws Exception{if(!Boolean.getBoolean("alien.scene.smoke"))return;m=Minecraft.getMinecraft();out=new File(System.getProperty("alien.scene.smoke.output"));Files.createDirectories(out.toPath());Files.deleteIfExists(new File(out,"result.txt").toPath());AlienClient.get().store().resetDefaults();start=since=System.nanoTime();FMLCommonHandler.instance().bus().register(this);}
 private long elapsed(long t){return (System.nanoTime()-t)/1000000;}
 @SubscribeEvent public void render(TickEvent.RenderTickEvent e){if(done||e.phase!=TickEvent.Phase.END)return;try{if(elapsed(start)>230000)throw new AssertionError("Deadline stage "+stage);long wait=stage==21?1400:stage==4?300:stage==3?400:stage==5?600:stage==6?140:stage>=15?950:900;if(elapsed(since)<wait)return;step();}catch(Throwable f){done=true;if(robot!=null)robot.keyRelease(java.awt.event.KeyEvent.VK_W);write(false,f);throw new RuntimeException(f);}}
 private void server(Runnable work)throws Exception{m.getIntegratedServer().addScheduledTask(work).get();}
 private EntityPlayerMP sp(){return m.getIntegratedServer().getConfigurationManager().playerEntityList.get(0);}
 private void next(){stage++;since=System.nanoTime();System.out.println("ALIEN_SCENE_STAGE "+stage);}
 private void require(boolean b,String s){if(!b)throw new AssertionError(s);checks.add(s);System.out.println("ALIEN_SCENE_CHECK "+s);}
 private void capture(String s)throws Exception{File f=new File(out,"screenshots/"+s+".png");Files.deleteIfExists(f.toPath());ScreenShotHelper.saveScreenshot(out,s+".png",m.displayWidth,m.displayHeight,m.getFramebuffer());BufferedImage im=ImageIO.read(f);require(im!=null&&im.getWidth()==m.displayWidth,"Real framebuffer "+s);require(GL11.glGetError()==GL11.GL_NO_ERROR,"Clean OpenGL after "+s);if(s.endsWith("sky")&&c().scenes.skyIndex()>0)skyFrames.add(skySamples(im));}
 /** Compare sky regions: different presets can legitimately share one RGB pixel. */
 private List<Integer> skySamples(BufferedImage image){
  List<Integer> samples=new ArrayList<Integer>();
  for(int y=image.getHeight()/10;y<image.getHeight()/3;y+=8)
   for(int x=image.getWidth()/4;x<image.getWidth()*3/4;x+=8)samples.add(image.getRGB(x,y));
  return samples;
 }
 private void step()throws Exception{SceneConfig fx=c().scenes;
  switch(stage){
   case 0:if(m.currentScreen==null)return;require(!fx.enabled,"Old profiles start with all new scene FX off");Display.setDisplayMode(new DisplayMode(1280,720));java.lang.reflect.Method resize=Minecraft.class.getDeclaredMethod("resize",int.class,int.class);resize.setAccessible(true);resize.invoke(m,1280,720);m.gameSettings.guiScale=2;m.gameSettings.limitFramerate=30;m.gameSettings.renderDistanceChunks=4;m.gameSettings.pauseOnLostFocus=false;m.launchIntegratedServer("AlienScenes-"+System.currentTimeMillis(),"Disposable scenes validation",new WorldSettings(42,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT));next();return;
   case 1:if(m.thePlayer==null||m.thePlayer.ticksExisted<40)return;m.displayGuiScreen(null);c().hud.applyPreset("Cinematic");c().cosmetics.self.hat="NONE";c().cosmetics.self.face="NONE";c().cosmetics.self.back="NONE";c().cosmetics.self.aura=false;c().effects.enabled=false;c().world.weather="Clear";c().world.cloudMode="Hidden";m.gameSettings.clouds=0;
    server(()->{EntityPlayerMP p=sp();p.worldObj.getGameRules().setOrCreateGameRule("doMobSpawning","false");p.worldObj.getGameRules().setOrCreateGameRule("doDaylightCycle","false");p.worldObj.setWorldTime(6000);p.setPositionAndUpdate(.5,4,.5);p.inventory.mainInventory[0]=new ItemStack(Items.diamond_sword);p.inventoryContainer.detectAndSendChanges();});m.gameSettings.thirdPersonView=2;m.thePlayer.rotationYaw=0;m.thePlayer.rotationPitch=-8;next();return;
   case 2:capture("71-scenes-baseline");fx.enabled=true;fx.shockwave=true;landings=SceneManager.landings();m.thePlayer.jump();next();return;
   case 3:if(m.thePlayer.onGround){if(elapsed(since)<2000)return;throw new AssertionError("Player did not jump");}next();return;
   case 4:if(!m.thePlayer.onGround){if(elapsed(since)<4000)return;throw new AssertionError("Player did not land");}require(SceneManager.landings()>landings&&SceneManager.waveCount()>0,"Real jump and landing emits a shockwave");frames=SceneShaders.frames();next();return;
   case 5:require(SceneShaders.status().startsWith("Ready"),"GLSL 1.20 scene and glass programs compile and link: "+SceneShaders.status());require(SceneShaders.frames()>frames,"Depth-based shockwave actually reaches the framebuffer");capture("72-shockwave-landing");fx.shockwave=false;fx.cute=true;cute=ScenePlayerLayer.cuteFrames();next();return;
   case 6:require(ScenePlayerLayer.cuteFrames()>cute,"Cute World draws original face art on the posed player");capture("73-cute-world");fx.cute=false;fx.mode="Cyberspace";frames=SceneShaders.frames();next();return;
   case 7:require(SceneShaders.frames()>frames,"Cyberspace applies actual depth-reconstructed grid shader");capture("74-cyberspace-world");fx.mode="Skeleton";bones=ScenePlayerLayer.boneFrames();next();return;
   case 8:require(ScenePlayerLayer.boneFrames()>bones,"X-Ray decorative bones follow the actual vanilla player pose");capture("75-xray-skeleton");server(()->{EntityPlayerMP p=sp();p.worldObj.getChunkFromChunkCoords(0,0);EntityItem drop=new EntityItem(p.worldObj,1.7,4.2,.5,new ItemStack(Items.diamond));drop.motionX=drop.motionY=drop.motionZ=0;drop.setInfinitePickupDelay();require(p.worldObj.spawnEntityInWorld(drop),"Integrated server actually spawns the dropped item in a loaded chunk");});fx.mode="Glass";glass=SceneShaders.glassDraws();bodyGlass=SceneManager.glassBodyDraws();heldGlass=SceneManager.glassHeldDraws();dropGlass=SceneManager.glassDroppedDraws();next();return;
   case 9:for(net.minecraft.entity.Entity entity:m.theWorld.loadedEntityList)if(entity instanceof EntityItem)System.out.println("SCENE_ITEM_DIAGNOSTIC "+entity.getPosition()+" "+m.getRenderManager().getEntityRenderObject(entity).getClass().getName());require(SceneShaders.glassDraws()>glass+1,"Glass shader draws player and real held/dropped item geometry");require(SceneManager.glassBodyDraws()>bodyGlass&&SceneManager.glassHeldDraws()>heldGlass&&SceneManager.glassDroppedDraws()>dropGlass,"Glass is applied separately to player/held/dropped geometry (counts "+SceneManager.glassBodyDraws()+"/"+SceneManager.glassHeldDraws()+"/"+SceneManager.glassDroppedDraws()+")");capture("76-glass-player-items");fx.mode="Chroma";frames=SceneShaders.frames();next();return;
   case 10:require(SceneManager.pathCount()>0&&SceneShaders.frames()>frames,"Chroma uses a real bounded player path and post process");capture("77-chroma-world");m.displayGuiScreen(new SceneStudioScreen(null));next();return;
   case 11:
    click(1);require(c().scenes.shockwave,"Scene Studio Shockwave button changes the real landing effect");click(1);
    click(2);require("CAPE".equals(c().cosmetics.self.back)&&c().cosmetics.self.capeShimmer,"Scene Studio Cape button enables actual animated Alien cape");
    click(3);require(c().cosmetics.self.trail&&"Ribbon".equals(c().cosmetics.self.trailStyle),"Scene Studio Trail button enables the existing real ribbon renderer");
    click(4);require(c().scenes.cute,"Cute World button edits the live face layer");click(4);
    for(int id=5;id<=8;id++){click(id);require(SceneConfig.MODES[id-4].equals(c().scenes.mode),"Scene Studio material selector "+SceneConfig.MODES[id-4]);}
    click(9);require("Cosmic".equals(c().scenes.sky),"Sky button cycles actual procedural sky selection");
    click(20);require(!c().scenes.enabled,"Scene FX master button disables the actual compositor");click(20);
    capture("78-scene-studio-controls");fx.sky="BlackHole";fx.mode="Natural";c().cosmetics.self.back="CAPE";c().cosmetics.self.capeShimmer=true;c().cosmetics.self.trail=true;AlienClient.get().store().saveProfile("scene_smoke");fx.sky="Off";require(AlienClient.get().store().loadProfile("scene_smoke"),"Unified scene profile reload succeeds");require("BlackHole".equals(c().scenes.sky)&&c().cosmetics.self.capeShimmer&&c().cosmetics.self.trail,"Scene settings, animated cape and trail persist together");m.displayGuiScreen(null);c().cosmetics.self.back="NONE";c().cosmetics.self.trail=false;m.thePlayer.rotationPitch=-35;m.gameSettings.thirdPersonView=1;next();return;
   case 12:capture("79-blackhole-sky");fx.sky="Cosmic";next();return;
   case 13:capture("80-cosmic-sky");cosmic=ImageIO.read(new File(out,"screenshots/80-cosmic-sky.png"));next();return;
   case 14:if(!animationCaptured){capture("90-cosmic-sky-animation");BufferedImage animated=ImageIO.read(new File(out,"screenshots/90-cosmic-sky-animation.png"));int changes=0;for(int y=20;y<cosmic.getHeight()/3;y+=4)for(int x=cosmic.getWidth()/4;x<cosmic.getWidth()*3/4;x+=4)if(cosmic.getRGB(x,y)!=animated.getRGB(x,y))changes++;require(changes>100,"Procedural sky visibly animates in consecutive actual framebuffer captures");animationCaptured=true;fx.sky="Aurora";since=System.nanoTime();return;}capture("81-aurora-living-sky");fx.sky="SnowClouds";next();return;
   case 15:capture("82-snow-clouds-sky");fx.sky="Fire";next();return;
   case 16:capture("83-fire-sky");fx.sky="Sunset";next();return;
   case 17:capture("84-sunset-sky");fx.sky="Ocean";next();return;
   case 18:capture("85-ocean-sky");fx.sky="Storm";next();return;
   case 19:capture("86-storm-sky");require(skyFrames.size()==8,"All eight sky presets have distinct sampled framebuffer regions");fx.enabled=false;frames=SceneShaders.frames();next();return;
   case 20:require(SceneShaders.frames()==frames,"Scene FX OFF leaves the original renderer untouched");require(SceneManager.waveCount()==0&&SceneManager.pathCount()==0,"OFF clears transient wave and chroma histories");capture("87-scene-fx-off-restored");require(sp().worldObj.getWorldTime()==6000,"Visual modes never change actual server time");fx.enabled=true;fx.mode="Chroma";fx.sky="Off";m.thePlayer.rotationPitch=22;m.gameSettings.thirdPersonView=1;robot=new java.awt.Robot();robot.keyPress(java.awt.event.KeyEvent.VK_W);next();return;
   case 21:robot.keyRelease(java.awt.event.KeyEvent.VK_W);require(SceneManager.pathCount()>1,"Actual X11 movement leaves multiple Chroma color-history samples");capture("88-chroma-moving-path");fx.enabled=false;m.loadWorld(null);m.displayGuiScreen(new net.minecraft.client.gui.GuiMainMenu());next();return;
   case 22:require(SceneManager.pathCount()==0&&SceneManager.waveCount()==0,"Disconnect clears all scene histories");capture("89-scene-after-disconnect");done=true;write(true,null);m.shutdown();return;
  }
 }
 private void click(int id)throws Exception{java.lang.reflect.Field field=GuiScreen.class.getDeclaredField("buttonList");field.setAccessible(true);for(Object obj:(java.util.List<?>)field.get(m.currentScreen)){GuiButton b=(GuiButton)obj;if(b.id==id){java.lang.reflect.Method method=SceneStudioScreen.class.getDeclaredMethod("actionPerformed",GuiButton.class);method.setAccessible(true);method.invoke(m.currentScreen,b);return;}}throw new AssertionError("Missing scene button "+id);}
 private void write(boolean pass,Throwable failure){try(PrintWriter w=new PrintWriter(new File(out,"result.txt"),"UTF-8")){w.println((pass?"PASS ":"FAIL stage "+stage+" ")+checks.size()+" checks");w.println("Actual Forge 1.8.9 / GLSL 1.20 / Linux software OpenGL; disposable integrated world");for(String s:checks)w.println("PASS "+s);if(failure!=null)failure.printStackTrace(w);}catch(Exception ignored){}}
}
